def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = _background(grid)
    # Paint only the interval between two same-colored markers in one row/column.
    for r in range(h):
        cols = [c for c, value in enumerate(grid[r]) if value != background]
        for i, c1 in enumerate(cols):
            for c2 in cols[i + 1:]:
                if grid[r][c1] == grid[r][c2]:
                    for c in range(c1 + 1, c2):
                        if grid[r][c] == background:
                            out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] != background]
        for i, r1 in enumerate(rows):
            for r2 in rows[i + 1:]:
                if grid[r1][c] == grid[r2][c]:
                    for r in range(r1 + 1, r2):
                        if grid[r][c] == background:
                            out[r][c] = 3
    return out


def _background(grid):
    from collections import Counter
    return Counter(v for row in grid for v in row).most_common(1)[0][0]


